#include <stdio.h>

int main(void) {
    unsigned int b[4];
    for (int i = 0; i < 4; i++) {
        if (scanf("%x", &b[i]) != 1) return 1;
    }
    if (b[0] == 0x7F && b[1] == 0x45 && b[2] == 0x4C && b[3] == 0x46)
        printf("ELF\n");
    else
        printf("khong phai ELF\n");
    return 0;
}
